function maxSumSubarrayK(nums, k) {
  let sum = 0;
  for (let i = 0; i < k; i += 1) sum += nums[i];
  let best = sum;
  for (let r = k; r < nums.length; r += 1) {
    sum += nums[r] - nums[r - k];
    best = Math.max(best, sum);
  }
  return best;
}

function maxProfit(prices) {
  let minPrice = Infinity;
  let best = 0;
  for (const p of prices) {
    minPrice = Math.min(minPrice, p);
    best = Math.max(best, p - minPrice);
  }
  return best;
}

function lengthOfLongestSubstring(s) {
  const last = new Map();
  let left = 0;
  let best = 0;
  for (let right = 0; right < s.length; right += 1) {
    const c = s[right];
    if (last.has(c) && last.get(c) >= left) left = last.get(c) + 1;
    last.set(c, right);
    best = Math.max(best, right - left + 1);
  }
  return best;
}

function characterReplacement(s, k) {
  const count = new Map();
  let left = 0;
  let maxFreq = 0;
  let best = 0;
  for (let right = 0; right < s.length; right += 1) {
    const c = s[right];
    count.set(c, (count.get(c) ?? 0) + 1);
    maxFreq = Math.max(maxFreq, count.get(c));
    while (right - left + 1 - maxFreq > k) {
      const lc = s[left];
      count.set(lc, count.get(lc) - 1);
      left += 1;
    }
    best = Math.max(best, right - left + 1);
  }
  return best;
}

function minWindow(s, t) {
  if (!t.length) return "";
  const need = new Map();
  for (const c of t) need.set(c, (need.get(c) ?? 0) + 1);
  let have = 0;
  const req = need.size;
  let left = 0;
  let bestLen = Infinity;
  let bestStart = 0;
  const window = new Map();
  for (let right = 0; right < s.length; right += 1) {
    const c = s[right];
    window.set(c, (window.get(c) ?? 0) + 1);
    if (need.has(c) && window.get(c) === need.get(c)) have += 1;
    while (have === req) {
      if (right - left + 1 < bestLen) {
        bestLen = right - left + 1;
        bestStart = left;
      }
      const lc = s[left];
      window.set(lc, window.get(lc) - 1);
      if (need.has(lc) && window.get(lc) < need.get(lc)) have -= 1;
      left += 1;
    }
  }
  return bestLen === Infinity ? "" : s.slice(bestStart, bestStart + bestLen);
}
